"use client";
import { motion } from "framer-motion";
import { PrimaryButton, SecondaryButton } from "./Buttons";

export default function HeroBlock({ person }: { person: any }) {
    const containerVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.3
            }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.8, ease: [0.22, 0.61, 0.36, 1] as any }
        }
    };

    return (
        <section className="relative min-h-screen flex flex-col justify-center px-6 md:px-12 pt-20 overflow-hidden">
            <div className="max-w-7xl mx-auto w-full relative z-10">
                <motion.div
                    variants={containerVariants}
                    initial="hidden"
                    animate="visible"
                    className="flex flex-col items-start"
                >
                    {/* Status Badge */}
                    <motion.div
                        variants={itemVariants}
                        className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-accent/5 border border-accent/20 mb-8"
                    >
                        <span className="relative flex h-2 w-2">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-accent opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2 w-2 bg-accent"></span>
                        </span>
                        <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-accent">
                            Available for new projects
                        </span>
                    </motion.div>

                    {/* Headline */}
                    <motion.h1
                        variants={itemVariants}
                        className="font-tight text-[48px] md:text-[80px] lg:text-[104px] font-bold leading-[1] tracking-[-0.04em] text-white mb-8 max-w-[1000px] text-gradient"
                    >
                        Designing Digital <br />
                        <span className="text-accent italic">Excellence.</span>
                    </motion.h1>

                    {/* Subtext */}
                    <motion.p
                        variants={itemVariants}
                        className="text-[18px] md:text-[20px] text-text-secondary max-w-[600px] leading-relaxed mb-12"
                    >
                        I am {person.name}, a Senior Product Designer dedicated to bridging the gap between complex technology and human-centric design.
                    </motion.p>

                    {/* CTA Group */}
                    <motion.div
                        variants={itemVariants}
                        className="flex flex-wrap items-center gap-6"
                    >
                        <PrimaryButton href="#work">Explore My Work</PrimaryButton>
                        <SecondaryButton href="#about">About My Process</SecondaryButton>
                    </motion.div>
                </motion.div>
            </div>

            {/* Decorative Element */}
            <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 0.4, scale: 1 }}
                transition={{ duration: 2, ease: "easeOut" }}
                className="absolute top-1/2 right-0 -translate-y-1/2 translate-x-1/2 w-[600px] h-[600px] bg-accent/10 rounded-full blur-[120px] -z-10"
            />
        </section>
    );
}
