"use client";
import { motion } from "framer-motion";
import Image from "next/image";
import { MoveRight } from "lucide-react";
import Link from "next/link";

export default function ProjectCard({ project, index }: { project: any, index: number }) {
    return (
        <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: index * 0.1, ease: [0.22, 0.61, 0.36, 1] }}
            className="group relative flex flex-col bg-bg-secondary border border-border rounded-[32px] overflow-hidden transition-premium hover:border-accent/40 hover:shadow-2xl hover:shadow-accent/10"
        >
            {/* Image Container */}
            <div className="relative aspect-[16/10] overflow-hidden">
                <img
                    src={project.image}
                    alt={project.title}
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-bg-secondary via-transparent to-transparent opacity-60" />

                {/* Floating Tag */}
                <div className="absolute top-6 left-6 flex items-center gap-2 px-3 py-1.5 rounded-full glass-card border-white/10">
                    <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
                    <span className="text-[10px] font-bold uppercase tracking-widest text-white">
                        {project.role}
                    </span>
                </div>
            </div>

            {/* Content */}
            <div className="p-8 md:p-10 flex flex-col flex-1">
                <div className="flex items-center justify-between mb-6">
                    <h3 className="text-2xl md:text-3xl font-bold text-white group-hover:text-accent transition-colors">
                        {project.title}
                    </h3>
                    <div className="w-12 h-12 rounded-full border border-border flex items-center justify-center group-hover:bg-accent group-hover:border-accent transition-premium group-hover:text-white">
                        <MoveRight className="w-5 h-5 group-hover:translate-x-0.5 transition-transform" />
                    </div>
                </div>

                <div className="space-y-4">
                    {project.bullets.map((bullet: string, i: number) => (
                        <div key={i} className="flex gap-3 text-text-secondary text-sm leading-relaxed">
                            <span className="text-accent mt-1">•</span>
                            {bullet}
                        </div>
                    ))}
                </div>

                <div className="mt-auto pt-10 flex items-center gap-4">
                    <Link
                        href={`/projects/${project.title.toLowerCase().replace(/ /g, "-")}`}
                        className="text-xs font-bold uppercase tracking-widest text-text-muted hover:text-white transition-colors"
                    >
                        Case Study
                    </Link>
                    <div className="h-[1px] flex-1 bg-border" />
                </div>
            </div>
        </motion.div>
    );
}
