"use client";
import { motion } from "framer-motion";
import Link from "next/link";
import { MoveRight } from "lucide-react";

interface ButtonProps {
    href: string;
    children: React.ReactNode;
    className?: string;
}

export const PrimaryButton = ({ href, children, className = "" }: ButtonProps) => {
    return (
        <Link href={href} className={`relative group inline-flex items-center gap-2 px-8 py-3.5 bg-accent text-white font-bold rounded-full overflow-hidden transition-premium hover:shadow-[0_0_20px_var(--color-accent-glow)] ${className}`}>
            <span className="relative z-10 flex items-center gap-2">
                {children}
                <MoveRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
            </span>
            <div className="absolute inset-0 bg-white/20 -translate-x-full group-hover:translate-x-full transition-transform duration-1000 ease-in-out" />
        </Link>
    );
};

export const SecondaryButton = ({ href, children, className = "" }: ButtonProps) => {
    return (
        <Link href={href} className={`relative group inline-flex items-center gap-2 px-8 py-3.5 bg-bg-secondary text-text-primary font-bold rounded-full border border-border overflow-hidden transition-premium hover:border-accent ${className}`}>
            <span className="relative z-10">{children}</span>
            <div className="absolute inset-0 bg-accent/5 opacity-0 group-hover:opacity-100 transition-opacity" />
        </Link>
    );
};

export const GhostButton = ({ href, children, className = "" }: ButtonProps) => {
    return (
        <Link href={href} className={`relative group inline-flex items-center gap-2 px-6 py-2 text-text-secondary hover:text-white font-medium transition-premium ${className}`}>
            <span className="relative z-10">{children}</span>
            <div className="absolute bottom-0 left-0 w-0 h-[1px] bg-accent group-hover:w-full transition-all duration-300" />
        </Link>
    );
};
